include <robotics.scad>
// PCB: origin at board center, bottom face z=0
W = 38; T = 1.4; hole_d = 2.5; pitch = 30; r_corner = 1;
diff() cuboid([W, W, T], rounding = r_corner, edges = "Z", anchor = BOT, $fn = 32) {
  tag("remove") grid_copies(spacing = pitch, n = 2) cyl(d = hole_d, h = T + 1, $fn = 32);
}

include <robotics.scad>
// Origin: board center, z=0 = PCB bottom face. Optical axis = +Z. Tripod tab toward -Y.
pcb_t = 1.4; body_h = 10.35; z0 = pcb_t; z1 = pcb_t + body_h;   // 1.4 .. 11.75
body_d = 30.75; bore_d = 22.4;
clamp_w = 10.16; clamp_d = 5.02; clamp_top = 21.5; slit = 0.8; slit_bot = 17.5; // top from drawing scale
tab_w = 13.97; tab_bot = -30.36; flare_w = 24.1;   // flare & drop scaled from drawing
tri_d = 6.35; tri_depth = 6; tri_z = z1 - 7.62/2;
$fn = 64;
difference() {
  union() {
    translate([0,0,z0]) cyl(d = body_d, h = body_h, anchor = BOT);
    // split clamp tab at top edge
    translate([-clamp_w/2, 10, z1 - clamp_d]) cube([clamp_w, clamp_top - 10, clamp_d]);
    // flare from body to tripod tab (in front of PCB)
    hull() {
      translate([-flare_w/2, -19, z0]) cube([flare_w, 3, body_h]);
      translate([-tab_w/2, -24, z0]) cube([tab_w, 1, body_h]);
      translate([-tab_w/2, -12, z0]) cube([tab_w, 1, body_h]);
    }
    // tripod tab below the board edge, back face flush with PCB bottom
    translate([-tab_w/2, tab_bot, 0]) cube([tab_w, -19 - tab_bot + 6, z1]);
  }
  translate([0,0,-1]) cyl(d = bore_d, h = 20, anchor = BOT);
  // keep PCB region clear (housing sits on PCB top)
  translate([-19.01, -19.01, -0.01]) cube([38.02, 38.02, pcb_t + 0.01]);
  // clamp slit
  translate([-slit/2, slit_bot, z1 - clamp_d - 0.1]) cube([slit, 10, clamp_d + 0.2]);
  // 1/4"-20 tripod hole from bottom face
  translate([0, tab_bot - 0.01, tri_z]) rotate([-90,0,0]) cylinder(d = tri_d, h = tri_depth);
}

include <robotics.scad>
$fn = 96;
difference() {
  union() {
    cyl(d = 36, h = 1.2, anchor = BOT);
    up(1.2) cyl(d = 30.75, h = 5.8, anchor = BOT);
  }
  down(1) cyl(d = 22.4, h = 10, anchor = BOT);
}

include <robotics.scad>
// Origin: board center, top face at z=0 (mates PCB bottom)
S = 39.5; D = 6.32; R = 4.75;
$fn = 48;
diff() cuboid([S, S, D], rounding = R, edges = "Z", anchor = TOP) {
  tag("remove") grid_copies(spacing = 30, n = 2) cyl(d = 5.99, h = D + 1);
  tag("remove") xcopies(24.38) cyl(d = 2.5, h = D + 1);
}
